const BASE = "https://raw.githubusercontent.com/pxulng/financial-report-analyst/main/data/10k/";
const REPORTS = [
  { id: "AAPL", file: "AAPL_10-K_FY2026.md" },
  { id: "MSFT", file: "MSFT_10-K_FY2026.md" },
  { id: "WMT", file: "WMT_10-K_FY2026.md" },
  { id: "NKE", file: "NKE_10-K_FY2026.md" },
  { id: "JNJ", file: "JNJ_10-K_FY2025.md" },
  { id: "XOM", file: "XOM_10-K_FY2025.md" },
  { id: "BA", file: "BA_10-K_FY2025.md" },
  { id: "SBUX", file: "SBUX_10-K_FY2025.md" },
  { id: "TSLA", file: "TSLA_10-K_FY2025.md" },
  { id: "JPM", file: "JPM_10-K_FY2025.md" }
];
return REPORTS.map(r => ({ json: { id: r.id, url: BASE + r.file } }));

const reports = $("Reports").all();
const outs = $input.all();
const textOf = (j) => (j && Array.isArray(j.content)) ? j.content.filter(c => c.type === "text").map(c => c.text).join("") : "";
const results = outs.map((it, i) => {
  const id = reports[i] ? reports[i].json.id : "unknown_" + i;
  const raw = textOf(it.json);
  let sheet = null, valid_json = false;
  try { sheet = JSON.parse(raw.replace(/^\s*```(?:json)?/i, "").replace(/```\s*$/, "").trim()); valid_json = true; } catch (e) {}
  const u = it.json.usage || {};
  return { id, model: it.json.model, stop_reason: it.json.stop_reason, valid_json, input_tokens: u.input_tokens ?? null, output_tokens: u.output_tokens ?? null, sheet, raw: valid_json ? undefined : raw };
});
return [{ json: { n: results.length, n_invalid: results.filter(r => !r.valid_json).length, results: JSON.stringify(results) } }];
